import { BUILD_RENAMED_COMPONENTS, isBuiltInComponent } from './builtInComponents.js';
import { remarkFrames } from './plugins/remark/remarkFrames.js';
import { coreRemark } from './remark.js';
import { allowedComponents } from './utils.js';
describe('isBuiltInComponent', () => {
    it('accepts every component remarkMdxRemoveUnknownJsx keeps', () => {
        expect(allowedComponents.filter((name) => !isBuiltInComponent(name))).toEqual([]);
        expect(isBuiltInComponent('Color.Row')).toBe(true);
        expect(isBuiltInComponent('Color.Nope')).toBe(false);
        expect(isBuiltInComponent('Missing')).toBe(false);
    });
    it('accepts tags the build rewrites before removing unknown JSX', () => {
        const tree = coreRemark().parse('<Example>\n  x\n</Example>\n');
        remarkFrames()(tree);
        const [node] = tree.children;
        expect(BUILD_RENAMED_COMPONENTS).toEqual(['Example', 'Snippet']);
        expect((node === null || node === void 0 ? void 0 : node.name) && allowedComponents.includes(node.name)).toBe(true);
        expect(BUILD_RENAMED_COMPONENTS.every(isBuiltInComponent)).toBe(true);
    });
});
